export function Scene({ name, className, still = false }: { name: SceneName; className?: string; still?: boolean }) {
  const uid = useId().replace(/[^a-zA-Z0-9]/g, '');
  return (
    <svg
      viewBox="0 0 400 400"
      className={cn('scene', !still && 'scene-float', className)}
      aria-hidden
      dangerouslySetInnerHTML={{ __html: SCENES[name].replaceAll('%ID%', `${uid}-`) }}
    />
  );
}
